param(
    [string]$Version,
    [string]$Dir,
    [switch]$NoSetup,
    [switch]$Yes,
    [switch]$Uninstall,
    [string]$From,
    [string]$Sha256,
    [switch]$Help
)

$script:InstallerArguments = @{
    Version = $Version
    Dir = $Dir
    NoSetup = $NoSetup.IsPresent
    Yes = $Yes.IsPresent
    Uninstall = $Uninstall.IsPresent
    From = $From
    Sha256 = $Sha256
    Help = $Help.IsPresent
}

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$script:UseUi = (-not [Console]::IsOutputRedirected) -and (-not $env:NO_COLOR) -and ($env:TERM -ne 'dumb')
$script:UseErrUi = (-not [Console]::IsErrorRedirected) -and (-not $env:NO_COLOR) -and ($env:TERM -ne 'dumb')
$script:Esc = [string][char]27
$script:Cr = [string][char]13

function Enable-VirtualTerminal {
    if (-not $script:UseUi -and -not $script:UseErrUi) { return }
    try {
        if (-not ('DrawplateInstaller.VtConsole' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
namespace DrawplateInstaller {
    public static class VtConsole {
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern IntPtr GetStdHandle(int nStdHandle);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool GetConsoleMode(IntPtr hConsoleHandle, out uint lpMode);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool SetConsoleMode(IntPtr hConsoleHandle, uint dwMode);
        public static bool Enable() {
            IntPtr handle = GetStdHandle(-11);
            if (handle == IntPtr.Zero || handle == new IntPtr(-1)) return false;
            uint mode;
            if (!GetConsoleMode(handle, out mode)) return false;
            if ((mode & 0x0004u) != 0) return true;
            return SetConsoleMode(handle, mode | 0x0004u);
        }
    }
}
'@ -ErrorAction Stop | Out-Null
        }
        if (-not [DrawplateInstaller.VtConsole]::Enable()) {
            $script:UseUi = $false
            $script:UseErrUi = $false
        }
    }
    catch {
        $script:UseUi = $false
        $script:UseErrUi = $false
    }
}

function Write-Ui([string]$Text) {
    [Console]::Out.Write($Text)
    [Console]::Out.Write([char]10)
}

$script:LabelWidth = 26
$script:G = @{}
$script:C = @{}
$script:Spinner = @()
$script:Utf8 = $false
$script:TrueColor = $false

function Get-Fg([int]$R, [int]$G, [int]$B) {
    if ($script:TrueColor) { return "$($script:Esc)[38;2;$R;$G;$($B)m" }
    $index = 16 + 36 * [int][Math]::Floor($R / 51.0 + 0.5) + 6 * [int][Math]::Floor($G / 51.0 + 0.5) + [int][Math]::Floor($B / 51.0 + 0.5)
    return "$($script:Esc)[38;5;$($index)m"
}

# Glyphs are built from code points so this file stays ASCII-only.
function Initialize-UiStyle {
    $script:Utf8 = $false
    if ($script:UseUi -or $script:UseErrUi) {
        try {
            if ([Console]::OutputEncoding.CodePage -ne 65001) {
                [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
            }
            $script:Utf8 = ([Console]::OutputEncoding.CodePage -eq 65001)
        }
        catch { $script:Utf8 = $false }
    }
    $script:TrueColor = ($env:COLORTERM -eq 'truecolor') -or ($env:COLORTERM -eq '24bit') -or ($env:OS -eq 'Windows_NT')
    $e = $script:Esc
    $script:C = @{
        Reset = "$e[0m"; Bold = "$e[1m"
        Ok = (Get-Fg 52 211 153); Info = (Get-Fg 56 189 248); Accent = (Get-Fg 34 211 238)
        Text = (Get-Fg 241 245 249); Soft = (Get-Fg 148 163 184); Muted = (Get-Fg 100 116 139)
        Err = (Get-Fg 248 113 113); Warn = (Get-Fg 251 191 36); G1 = (Get-Fg 16 185 129); G4 = (Get-Fg 139 92 246)
        Dim = (Get-Fg 51 65 85)
    }
    if ($script:Utf8) {
        $script:G = @{
            Full = [string][char]0x2588; H = [string][char]0x2500; V = [string][char]0x2502
            TL = [string][char]0x256D; TR = [string][char]0x256E; BL = [string][char]0x2570; BR = [string][char]0x256F
            Bar = [string][char]0x2501; Ok = [string][char]0x2713; Skip = [string][char]0x25CB
            Err = [string][char]0x2717; Warn = [string][char]0x25B2; Dot = [string][char]0x00B7
        }
        $script:Spinner = @(0x280B, 0x2819, 0x2839, 0x2838, 0x283C, 0x2834, 0x2826, 0x2827, 0x2807, 0x280F | ForEach-Object { [string][char]$_ })
    }
    else {
        $script:G = @{
            Full = '#'; H = '-'; V = '|'; TL = '+'; TR = '+'; BL = '+'; BR = '+'
            Bar = '='; Ok = '+'; Skip = 'o'; Err = 'x'; Warn = '!'; Dot = '|'
        }
        $script:Spinner = @('|', '/', '-', '\')
    }
    $script:ArtMap = @{ '#' = $script:G.Full; '-' = $script:G.H; '<' = $script:G.TL; '>' = $script:G.TR; '{' = $script:G.BL; '}' = $script:G.BR }
}

# Four-stop gradient: green, cyan, blue, violet.
function Get-GradientColor([double]$T) {
    if ($T -lt 0) { $T = 0 }
    if ($T -gt 1) { $T = 1 }
    $stops = @(@(16, 185, 129), @(6, 182, 212), @(59, 130, 246), @(139, 92, 246))
    $segment = [Math]::Min(2, [int][Math]::Floor($T * 3))
    $u = $T * 3 - $segment
    $from = $stops[$segment]
    $to = $stops[$segment + 1]
    return [int[]]@(
        [int]($from[0] + ($to[0] - $from[0]) * $u),
        [int]($from[1] + ($to[1] - $from[1]) * $u),
        [int]($from[2] + ($to[2] - $from[2]) * $u))
}

# Paints ASCII art diagonally; art symbols map to glyphs.
function Format-GradientArt([string]$Art, [int]$Row, [int]$Width) {
    if (-not $script:UseUi) { return $Art }
    $sb = [System.Text.StringBuilder]::new($Art.Length * 24)
    for ($i = 0; $i -lt $Art.Length; $i++) {
        $ch = [string]$Art[$i]
        if ($ch -eq ' ') {
            [void]$sb.Append(' ')
            continue
        }
        $rgb = Get-GradientColor (($i + $Row * 3) / ($Width + 14.0))
        [void]$sb.Append((Get-Fg $rgb[0] $rgb[1] $rgb[2]))
        if ($script:ArtMap.ContainsKey($ch)) { [void]$sb.Append($script:ArtMap[$ch]) } else { [void]$sb.Append($ch) }
    }
    [void]$sb.Append($script:C.Reset)
    return $sb.ToString()
}

function Format-ProgressBar([int]$Width, [double]$Fraction) {
    $filled = [Math]::Min($Width, [Math]::Max(0, [int][Math]::Round($Fraction * $Width)))
    $sb = [System.Text.StringBuilder]::new($Width * 24)
    for ($i = 0; $i -lt $Width; $i++) {
        if ($i -lt $filled) {
            $rgb = Get-GradientColor ([double]$i / [Math]::Max(1, $Width - 1))
            [void]$sb.Append((Get-Fg $rgb[0] $rgb[1] $rgb[2]))
        }
        else {
            [void]$sb.Append($script:C.Dim)
        }
        [void]$sb.Append($script:G.Bar)
    }
    [void]$sb.Append($script:C.Reset)
    return $sb.ToString()
}

# Normalises "Finding release ........" to a fixed-width column.
function Split-StepLabel([string]$Label) {
    $text = $Label.TrimEnd(' ', '.')
    $dots = [Math]::Max(0, $script:LabelWidth - $text.Length - 1)
    return [pscustomobject]@{ Text = $text; Leader = ('.' * $dots) }
}

function Write-Banner([string]$PkgVersion) {
    if (-not $script:UseUi) {
        Write-Ui "Drawplate installer $PkgVersion"
        return
    }
    $c = $script:C
    $art = @(
        '####  ####   ###  #   # ####  #      ###  ##### #####',
        '#   # #   # #   # #   # #   # #     #   #   #   #',
        '#   # ####  ##### # # # ####  #     #####   #   ####',
        '#   # #  #  #   # ## ## #     #     #   #   #   #',
        '####  #   # #   # #   # #     ##### #   #   #   #####'
    )
    Write-Ui ''
    for ($row = 0; $row -lt $art.Count; $row++) {
        Write-Ui ('  ' + (Format-GradientArt $art[$row] $row 53))
        Start-Sleep -Milliseconds 40
    }
    Write-Ui ('  ' + (Format-GradientArt ('-' * 53) 5 53))
    Write-Ui ('  ' + $c.Soft + 'Drawplate installer' + $c.Reset + ' ' + $c.Accent + $PkgVersion + $c.Reset)
    Write-Ui ''
}

function Write-Step([string]$Tag, [string]$Label, [string]$Badge, [string]$Detail) {
    if (-not $script:UseUi) {
        if ($Detail) { Write-Ui "$Tag $Label $Badge $Detail" }
        elseif ($Badge) { Write-Ui "$Tag $Label $Badge" }
        else { Write-Ui "$Tag $Label" }
        return
    }
    $c = $script:C
    $parts = Split-StepLabel $Label
    switch ($Badge) {
        '[ok]' { $glyph = $script:G.Ok; $glyphColor = $c.Ok; $labelColor = $c.Text; $detailColor = $c.Soft }
        '[skipped]' { $glyph = $script:G.Skip; $glyphColor = $c.Muted; $labelColor = $c.Muted; $detailColor = $c.Muted }
        default { $glyph = $script:G.Skip; $glyphColor = $c.Info; $labelColor = $c.Text; $detailColor = $c.Soft }
    }
    Write-Ui ('  ' + $glyphColor + $glyph + $c.Reset + '  ' + $c.Info + $Tag.Trim('[', ']') + $c.Reset + '  ' +
        $labelColor + $parts.Text + $c.Reset + ' ' + $c.Muted + $parts.Leader + $c.Reset + '  ' + $detailColor + $Detail + $c.Reset)
}

function Write-UiNote([string]$Text) {
    if (-not $script:UseUi) {
        Write-Ui $Text
        return
    }
    $c = $script:C
    if ($Text.StartsWith('Note:')) {
        Write-Ui ''
        Write-Ui ('  ' + $c.Warn + $script:G.Warn + $c.Reset + ' ' + $c.Soft + $Text + $c.Reset)
    }
    else {
        Write-Ui ('  ' + $c.Soft + $Text + $c.Reset)
    }
}

function Format-BoxRow([string]$Plain, [string]$Colored, [int]$Inner) {
    $c = $script:C
    $pad = ' ' * [Math]::Max(0, $Inner - $Plain.Length)
    return '  ' + $c.G1 + $script:G.V + $c.Reset + $Colored + $pad + $c.G4 + $script:G.V + $c.Reset
}

function Write-DoneBox([string]$PkgVersion, [string]$BinaryPath) {
    if (-not $script:UseUi) {
        Write-Ui ''
        Write-Ui "Installed Drawplate $PkgVersion to $BinaryPath"
        Write-Ui 'Next:'
        Write-Ui '  drawplate --help'
        Write-Ui '  drawplate setup        (shows how to install FFmpeg)'
        return
    }
    $c = $script:C
    $plain1 = "  o Installed Drawplate $PkgVersion"
    $plain2 = "    Path: $BinaryPath"
    $plain3 = '    Next: drawplate --help  .  drawplate setup'
    $inner = 58
    foreach ($plain in @($plain1, $plain2, $plain3)) {
        if (($plain.Length + 2) -gt $inner) { $inner = $plain.Length + 2 }
    }
    Write-Ui ''
    Write-Ui ('  ' + (Format-GradientArt ('<' + ('-' * $inner) + '>') 0 ($inner + 2)))
    Write-Ui (Format-BoxRow '' '' $inner)
    Write-Ui (Format-BoxRow $plain1 ('  ' + $c.Ok + $script:G.Ok + $c.Reset + ' ' + $c.Bold + $c.Text + 'Installed Drawplate' + $c.Reset + ' ' + $c.Accent + $PkgVersion + $c.Reset) $inner)
    Write-Ui (Format-BoxRow $plain2 ('    ' + $c.Muted + 'Path:' + $c.Reset + ' ' + $c.Text + $BinaryPath + $c.Reset) $inner)
    Write-Ui (Format-BoxRow $plain3 ('    ' + $c.Muted + 'Next:' + $c.Reset + ' ' + $c.Info + 'drawplate --help' + $c.Reset + '  ' + $c.Muted + $script:G.Dot + $c.Reset + '  ' + $c.Info + 'drawplate setup' + $c.Reset) $inner)
    Write-Ui (Format-BoxRow '' '' $inner)
    Write-Ui ('  ' + (Format-GradientArt ('{' + ('-' * $inner) + '}') 4 ($inner + 2)))
}

# Live download line: spinner, step, label, gradient bar, percent, size, speed.
function Write-DownloadLine([long]$Received, $Total, [double]$Seconds, [int]$Tick) {
    $c = $script:C
    $parts = Split-StepLabel 'Downloading Drawplate'
    $hasTotal = $Total -and $Total -gt 0
    $frac = if ($hasTotal) { [double]$Received / $Total } else { ($Tick % 20) / 20.0 }
    $pct = if ($hasTotal) { '{0,3}%' -f [int](100 * $frac) } else { ' --%' }
    $mib = $Received / 1048576.0
    $stats = '{0:0.0} MiB' -f $mib
    if ($Seconds -ge 1) { $stats += ('  {0:0.0} MiB/s' -f ($mib / $Seconds)) }
    $spin = $script:Spinner[$Tick % $script:Spinner.Count]
    [Console]::Out.Write($script:Cr + '  ' + $c.Accent + $spin + $c.Reset + '  ' + $c.Info + '3/8' + $c.Reset + '  ' + $c.Text + $parts.Text + $c.Reset + ' ' +
        $c.Muted + $parts.Leader + $c.Reset + '  ' + (Format-ProgressBar 16 $frac) + ' ' + $c.Accent + $pct + $c.Reset + '  ' + $c.Soft + $stats + $c.Reset + $script:Esc + '[K')
}

function Write-InstallerError([string]$Text, [string]$Hint) {
    if ($script:UseErrUi) {
        $c = $script:C
        [Console]::Error.WriteLine('')
        [Console]::Error.WriteLine('  ' + $c.Err + $script:G.Err + ' Error:' + $c.Reset + ' ' + $Text)
        [Console]::Error.WriteLine('  ' + $c.Info + $script:G.Dot + ' Hint:' + $c.Reset + '  ' + $c.Soft + $Hint + $c.Reset)
        [Console]::Error.WriteLine('')
    }
    else {
        [Console]::Error.WriteLine("Error: $Text")
        [Console]::Error.WriteLine("Hint: $Hint")
    }
}

function Get-Sha256([string]$Path) {
    return (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant()
}

function Get-LatestTag([string]$BaseUrl) {
    Add-Type -AssemblyName System.Net.Http
    if ($PSVersionTable.PSEdition -ne 'Core') {
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    }
    [System.Net.WebRequest]::DefaultWebProxy.Credentials = [System.Net.CredentialCache]::DefaultCredentials
    $handler = [System.Net.Http.HttpClientHandler]::new()
    $handler.AllowAutoRedirect = $false
    $handler.DefaultProxyCredentials = [System.Net.CredentialCache]::DefaultCredentials
    $client = [System.Net.Http.HttpClient]::new($handler)
    $client.Timeout = [TimeSpan]::FromSeconds(30)
    try {
        $request = [System.Net.Http.HttpRequestMessage]::new([System.Net.Http.HttpMethod]::Head, "$BaseUrl/latest")
        $response = $client.SendAsync($request).GetAwaiter().GetResult()
        if (-not $response.Headers.Location) {
            $headerText = $response.Headers.ToString().Trim()
            Write-InstallerError "Latest release endpoint returned HTTP $([int]$response.StatusCode) without a Location header ($headerText)." 'Check the release endpoint, or set DRAWPLATE_VERSION to a known tag.'
            return ''
        }
        $target = [System.Uri]::new([System.Uri]::new($BaseUrl + '/latest'), $response.Headers.Location)
        $targetPath = $target.AbsolutePath.TrimEnd('/')
        $lastSlash = $targetPath.LastIndexOf('/')
        if ($lastSlash -lt 0) { return '' }
        return $targetPath.Substring($lastSlash + 1)
    }
    finally {
        $client.Dispose()
        $handler.Dispose()
    }
}

function Get-HttpFile([string]$Url, [string]$Destination, [bool]$ShowUiBar = $true) {
    Add-Type -AssemblyName System.Net.Http
    if ($PSVersionTable.PSEdition -ne 'Core') {
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    }
    [System.Net.WebRequest]::DefaultWebProxy.Credentials = [System.Net.CredentialCache]::DefaultCredentials
    $handler = [System.Net.Http.HttpClientHandler]::new()
    $handler.DefaultProxyCredentials = [System.Net.CredentialCache]::DefaultCredentials
    $client = [System.Net.Http.HttpClient]::new($handler)
    $client.Timeout = [TimeSpan]::FromMinutes(30)
    try {
        $response = $client.GetAsync($Url, [System.Net.Http.HttpCompletionOption]::ResponseHeadersRead).GetAwaiter().GetResult()
        [void]$response.EnsureSuccessStatusCode()
        $total = $response.Content.Headers.ContentLength
        $inputStream = $response.Content.ReadAsStreamAsync().GetAwaiter().GetResult()
        $outputStream = [System.IO.File]::Create($Destination)
        try {
            $buffer = [byte[]]::new(81920)
            $watch = [System.Diagnostics.Stopwatch]::StartNew()
            $tick = 0
            if ($script:UseUi -and $ShowUiBar) { [Console]::Out.Write($script:Esc + '[?25l') }
            [long]$received = 0
            $nextPercent = 25
            $lastDraw = [DateTime]::MinValue
            while (($read = $inputStream.Read($buffer, 0, $buffer.Length)) -gt 0) {
                $outputStream.Write($buffer, 0, $read)
                $received += $read
                if ($script:UseUi -and $ShowUiBar) {
                    $now = [DateTime]::UtcNow
                    if (($now - $lastDraw).TotalMilliseconds -ge 90) {
                        $lastDraw = $now
                        Write-DownloadLine $received $total $watch.Elapsed.TotalSeconds $tick
                        $tick++
                    }
                }
                else {
                    if ($total -and $total -gt 0) {
                        $percent = [int](100 * $received / $total)
                        while ($percent -ge $nextPercent -and $nextPercent -le 100) {
                            Write-Ui ("      {0}%" -f $nextPercent)
                            $nextPercent += 25
                        }
                    }
                }
            }
            if ($script:UseUi -and $ShowUiBar) {
                [Console]::Out.Write($script:Cr + $script:Esc + '[K')
                Write-Step '[3/8]' 'Downloading Drawplate' '[ok]' ('{0:0.0} MiB in {1}s' -f ($received / 1048576.0), [int][Math]::Round($watch.Elapsed.TotalSeconds))
            }
            else {
                while ($nextPercent -le 100) {
                    Write-Ui ("      {0}%" -f $nextPercent)
                    $nextPercent += 25
                }
            }
        }
        finally {
            if ($script:UseUi -and $ShowUiBar) { [Console]::Out.Write($script:Esc + '[?25h') }
            $outputStream.Dispose()
            $inputStream.Dispose()
        }
    }
    finally {
        $client.Dispose()
        $handler.Dispose()
    }
}

function Test-ProgramVersion([string]$Path, [string]$Expected) {
    try {
        $start = [System.Diagnostics.ProcessStartInfo]::new()
        $start.FileName = $Path
        $start.Arguments = '--version'
        $start.UseShellExecute = $false
        $start.RedirectStandardOutput = $true
        $start.RedirectStandardError = $true
        $process = [System.Diagnostics.Process]::new()
        $process.StartInfo = $start
        if (-not $process.Start()) {
            return $false
        }
        if (-not $process.WaitForExit(10000)) {
            try { $process.Kill() } catch { Write-InstallerError 'The timed-out process could not be stopped.' 'Stop it manually before retrying.' }
            return $false
        }
        $output = $process.StandardOutput.ReadToEnd().Trim()
        return ($process.ExitCode -eq 0 -and $output -eq "drawplate $Expected")
    }
    catch {
        return $false
    }
}

function Invoke-DrawplateInstall {
    Enable-VirtualTerminal
    Initialize-UiStyle
    $repo = $env:DRAWPLATE_REPO
    if (-not $repo) { $repo = 'migueljocode/Drawplate' }
    $baseUrl = $env:DRAWPLATE_BASE_URL
    if (-not $baseUrl) { $baseUrl = "https://github.com/$repo/releases" }

    if (-not $script:InstallerArguments.Version) { $script:InstallerArguments.Version = $env:DRAWPLATE_VERSION }
    if (-not $script:InstallerArguments.Dir) { $script:InstallerArguments.Dir = $env:DRAWPLATE_INSTALL_DIR }
    if (-not $script:InstallerArguments.From) { $script:InstallerArguments.From = $env:DRAWPLATE_FROM_ARCHIVE }
    if (-not $script:InstallerArguments.Sha256) { $script:InstallerArguments.Sha256 = $env:DRAWPLATE_SHA256 }

    $noSetup = [bool]$script:InstallerArguments.NoSetup
    $yes = [bool]$script:InstallerArguments.Yes
    $uninstall = [bool]$script:InstallerArguments.Uninstall
    if ($env:DRAWPLATE_NO_SETUP -eq '1' -or $env:DRAWPLATE_NO_SETUP -eq 'true') { $noSetup = $true }
    if ($env:DRAWPLATE_YES -eq '1' -or $env:DRAWPLATE_YES -eq 'true') { $yes = $true }
    if ($env:DRAWPLATE_UNINSTALL -eq '1' -or $env:DRAWPLATE_UNINSTALL -eq 'true') { $uninstall = $true }

    if ($script:InstallerArguments.Help) {
        Write-Ui 'Usage: install.ps1 [-Version <tag>] [-Dir <folder>] [-NoSetup] [-Yes] [-Uninstall] [-From <archive> -Sha256 <hash>] [-Help]'
        return 0
    }

    if ($script:InstallerArguments.From -and -not $script:InstallerArguments.Sha256) {
        Write-InstallerError '--sha256 is required with --from.' 'Provide the archive SHA-256 hash.'
        return 10
    }

    if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage') {
        Write-InstallerError 'This PowerShell session blocks scripts.' 'Run: powershell -NoProfile -ExecutionPolicy Bypass -File .\\install.ps1'
        return 16
    }

    if ([Environment]::OSVersion.Platform -ne [PlatformID]::Win32NT -or -not [Environment]::Is64BitOperatingSystem) {
        Write-InstallerError 'Unsupported platform.' 'Supported: linux-x64, linux-arm64, osx-arm64, win-x64.'
        return 11
    }

    $localAppData = $env:LOCALAPPDATA
    $binDir = $script:InstallerArguments.Dir
    if (-not $binDir) { $binDir = Join-Path $localAppData 'Programs\Drawplate' }
    $dataDir = Join-Path $localAppData 'Drawplate'
    $binary = Join-Path $binDir 'drawplate.exe'
    $manifest = Join-Path $dataDir 'install.json'

    if ($uninstall) {
        if (Test-Path -LiteralPath $manifest) {
            try {
                $saved = Get-Content -LiteralPath $manifest -Raw | ConvertFrom-Json
                if ($saved.path) { $binary = [string]$saved.path }
            }
            catch { Write-InstallerError 'The operation could not complete.' 'Check the error details and retry.' }
        }
        Write-Step '[1/4]' 'Locating installation .....' '[ok]' 'done'
        Write-Step '[2/4]' 'Removing files ............' '[ok]' 'done'
        Remove-Item -LiteralPath $binary -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath "$binary.old" -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $manifest -Force -ErrorAction SilentlyContinue
        $currentPath = [Environment]::GetEnvironmentVariable('Path', 'User')
        $kept = @()
        foreach ($entry in ($currentPath -split ';')) {
            if ($entry -and $entry.TrimEnd('\','/') -ne $binDir.TrimEnd('\','/')) { $kept += $entry }
        }
        [Environment]::SetEnvironmentVariable('Path', ($kept -join ';'), 'User')
        Write-Step '[3/4]' 'Updating PATH .............' '[ok]' 'done'
        if ((Test-Path -LiteralPath $binDir) -and -not (Get-ChildItem -LiteralPath $binDir -Force)) {
            Remove-Item -LiteralPath $binDir -Force
        }
        if ((Test-Path -LiteralPath $dataDir) -and -not (Get-ChildItem -LiteralPath $dataDir -Force)) {
            Remove-Item -LiteralPath $dataDir -Force
        }
        Write-Step '[4/4]' 'Finishing .................' '[ok]' 'done'
        Write-UiNote 'Removed Drawplate. FFmpeg was not touched.'
        return 0
    }

    if (-not $script:InstallerArguments.Version) {
        try { $script:InstallerArguments.Version = Get-LatestTag $baseUrl }
        catch { Write-InstallerError "Could not resolve the latest release ($($_.Exception.Message))." 'Set DRAWPLATE_VERSION to a known release tag and retry.'; $script:InstallerArguments.Version = '' }
    }
    if (-not $script:InstallerArguments.Version) {
        Write-InstallerError "Could not find a release for $repo." 'Check your internet connection, or set DRAWPLATE_VERSION.'
        return 12
    }

    $tag = $script:InstallerArguments.Version
    $pkgVersion = $tag.TrimStart('v')
    Write-Banner $pkgVersion

    $rid = 'win-x64'
    $archive = "drawplate-$tag-$rid.zip"
    $url = "$baseUrl/download/$tag/$archive"

    New-Item -ItemType Directory -Path $dataDir -Force | Out-Null
    $lockDir = Join-Path $dataDir '.lock'
    if (Test-Path -LiteralPath $lockDir) {
        $age = (Get-Date) - (Get-Item -LiteralPath $lockDir).LastWriteTime
        if ($age.TotalMinutes -lt 30) {
            Write-InstallerError "Another installation is running (lock: $lockDir)." 'Wait for it, or delete that folder if no installer is running.'
            return 15
        }
        Remove-Item -LiteralPath $lockDir -Recurse -Force
    }
    New-Item -ItemType Directory -Path $lockDir -Force | Out-Null

    $staging = Join-Path $binDir ('.drawplate-staging-' + [Guid]::NewGuid().ToString('N'))
    $repair = $false
    try {
        if ((Test-Path -LiteralPath $manifest) -and (Test-Path -LiteralPath $binary)) {
            $saved = Get-Content -LiteralPath $manifest -Raw | ConvertFrom-Json
            if ($saved.version -eq $pkgVersion -and (Get-Sha256 $binary) -eq $saved.binarySha256 -and (Test-ProgramVersion $binary $pkgVersion)) {
                Write-Step '[1/8]' 'Detecting platform .....' '[ok]' $rid
                Write-Step '[2/8]' 'Finding release ........' '[ok]' $tag
                Write-Step '[3/8]' 'Downloading Drawplate ....' '[skipped]' 'up to date'
                Write-Step '[4/8]' 'Downloading checksums ....' '[skipped]' 'up to date'
                Write-Step '[5/8]' 'Verifying checksum .......' '[skipped]' 'up to date'
                Write-Step '[6/8]' 'Installing .............' '[skipped]' 'up to date'
                Write-Step '[7/8]' 'Checking the install ....' '[skipped]' 'up to date'
                Write-Step '[8/8]' 'Finishing ..............' '[ok]' 'done'
                Write-DoneBox $pkgVersion $binary
                return 0
            }
            $repair = $true
        }

        New-Item -ItemType Directory -Path $binDir -Force | Out-Null
        New-Item -ItemType Directory -Path $staging -Force | Out-Null
        $archivePath = Join-Path $staging $archive

        Write-Step '[1/8]' 'Detecting platform .....' '[ok]' $rid
        Write-Step '[2/8]' 'Finding release ........' '[ok]' $tag
        if (-not $script:UseUi) { Write-Step '[3/8]' 'Downloading Drawplate ....' '' '' }

        if ($script:InstallerArguments.From) {
            Copy-Item -LiteralPath $script:InstallerArguments.From -Destination $archivePath
            if ($script:UseUi) { Write-Step '[3/8]' 'Downloading Drawplate' '[ok]' ('{0:0.0} MiB in 0s' -f ((Get-Item -LiteralPath $archivePath).Length / 1048576.0)) }
            $expectedHash = $script:InstallerArguments.Sha256.ToLowerInvariant()
        }
        else {
            try {
                Get-HttpFile $url $archivePath
                $sumsPath = Join-Path $staging 'SHA256SUMS'
                Get-HttpFile "$baseUrl/download/$tag/SHA256SUMS" $sumsPath $false
            }
            catch {
                Write-InstallerError "Download failed: $url ($($_.Exception.Message))." 'Retry, or download the archive yourself and use --from <archive> --sha256 <hash>.'
                return 12
            }
            $line = Get-Content -LiteralPath $sumsPath | Where-Object { $_ -match [regex]::Escape($archive) } | Select-Object -First 1
            if (-not $line) {
                Write-InstallerError "Checksum mismatch for $archive." 'Nothing was installed. Retry; if it repeats, report it.'
                return 13
            }
            $expectedHash = ($line -split '\s+')[0].ToLowerInvariant()
        }

        $actualHash = Get-Sha256 $archivePath
        if ($actualHash -ne $expectedHash) {
            Write-InstallerError "Checksum mismatch for $archive." 'Nothing was installed. Retry; if it repeats, report it.'
            return 13
        }
        Write-Step '[4/8]' 'Downloading checksums ....' '[ok]' 'done'
        Write-Step '[5/8]' 'Verifying checksum .......' '[ok]' 'done'

        Add-Type -AssemblyName System.IO.Compression.FileSystem
        $zip = [System.IO.Compression.ZipFile]::OpenRead($archivePath)
        try {
            $names = @($zip.Entries | ForEach-Object { $_.FullName })
            if ($names.Count -ne 3 -or $names -notcontains 'drawplate.exe' -or $names -notcontains 'LICENSE' -or $names -notcontains 'THIRD-PARTY-NOTICES.md') {
                Write-InstallerError "Could not install to $binDir." 'The archive contains unexpected files.'
                return 14
            }
        }
        finally {
            $zip.Dispose()
        }

        $extractDir = Join-Path $staging 'x'
        [System.IO.Compression.ZipFile]::ExtractToDirectory($archivePath, $extractDir)
        if (Test-Path -LiteralPath $binary) { Move-Item -LiteralPath $binary -Destination "$binary.old" -Force }
        Move-Item -LiteralPath (Join-Path $extractDir 'drawplate.exe') -Destination $binary -Force

        if (-not (Test-ProgramVersion $binary $pkgVersion)) {
            Remove-Item -LiteralPath $binary -Force -ErrorAction SilentlyContinue
            if (Test-Path -LiteralPath "$binary.old") { Move-Item -LiteralPath "$binary.old" -Destination $binary -Force }
            Write-InstallerError 'The installed program did not start or reported the wrong version. The previous version was restored.' 'Retry with a verified release archive.'
            return 14
        }
        Remove-Item -LiteralPath "$binary.old" -Force -ErrorAction SilentlyContinue

        $manifestObject = @{
            version = $pkgVersion
            rid = $rid
            archiveSha256 = $actualHash
            binarySha256 = (Get-Sha256 $binary)
            installedAt = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
            path = $binary
        }
        $manifestText = $manifestObject | ConvertTo-Json -Compress
        [System.IO.Directory]::CreateDirectory($dataDir) | Out-Null
        $tempManifest = "$manifest.tmp"
        [System.IO.File]::WriteAllText($tempManifest, $manifestText, (New-Object System.Text.UTF8Encoding($false)))
        Move-Item -LiteralPath $tempManifest -Destination $manifest -Force

        if ($repair) {
            Write-Step '[6/8]' 'Installing .............' '[ok]' 'repairing'
        }
        else {
            Write-Step '[6/8]' 'Installing .............' '[ok]' 'done'
        }
        Write-Step '[7/8]' 'Checking the install ....' '[ok]' 'done'
        Write-Step '[8/8]' 'Finishing ..............' '[ok]' 'done'
        Write-DoneBox $pkgVersion $binary

        $currentPath = [Environment]::GetEnvironmentVariable('Path', 'User')
        $entries = @()
        foreach ($entry in ($currentPath -split ';')) {
            if ($entry) { $entries += $entry }
        }
        $found = $false
        foreach ($entry in $entries) {
            if ($entry.TrimEnd('\','/') -ieq $binDir.TrimEnd('\','/')) { $found = $true }
        }
        if (-not $found) {
            $entries += $binDir
            [Environment]::SetEnvironmentVariable('Path', ($entries -join ';'), 'User')
            [Environment]::SetEnvironmentVariable('Path', ($entries -join ';'), 'Process')
            Write-UiNote "Your user PATH was updated. Open a new terminal to use 'drawplate'."
        }

        $ffmpegMissing = -not (Get-Command ffmpeg -ErrorAction SilentlyContinue)
        if ($ffmpegMissing) {
            Write-UiNote 'FFmpeg was not found on this machine.'
            if ($yes) {
                try { & $binary setup } catch { Write-InstallerError 'Could not run Drawplate setup.' 'Run drawplate setup manually.' }
            }
            elseif (-not $noSetup -and -not [Console]::IsInputRedirected) {
                $answer = Read-Host "Run 'drawplate setup' now? [Y/n]"
                if ($answer -ne 'n' -and $answer -ne 'N') {
                    try { & $binary setup } catch { Write-InstallerError 'Could not run Drawplate setup.' 'Run drawplate setup manually.' }
                }
            }
        }
        return 0
    }
    catch {
        Write-InstallerError "Could not install to $binDir ($($_.Exception.Message))." 'Choose another folder with DRAWPLATE_INSTALL_DIR.'
        return 14
    }
    finally {
        Remove-Item -LiteralPath $lockDir -Recurse -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction SilentlyContinue
    }
}

$exitCode = [int](Invoke-DrawplateInstall)
$global:LASTEXITCODE = $exitCode
$scriptPath = $PSCommandPath
if (-not $scriptPath) { $scriptPath = $MyInvocation.MyCommand.Path }
if ($scriptPath) {
    [Environment]::Exit($exitCode)
}
return
